/**
* Forward-compatible enum policy for values received from remote servers or DB rows:
* preserve the raw string, render an explicit fallback, and disable behavior that
* requires a known value. Never silently coerce an unknown value to a known variant.
*/
export const IPC_UNKNOWN_ENUM_POLICY = {
preserveRawValue: true,
unknownBehavior: "render-fallback-and-disable-unsupported-action",
} as const;

declare const unknownEnumBrand: unique symbol;
export type UnknownEnumValue = string & { readonly [unknownEnumBrand]: true };
export type ForwardCompatibleEnum<Known extends string> =
| Known
| UnknownEnumValue;

